async function main() {
  // Dachgeometrie: Gebäude 6 x 4 m, First verläuft Ost-West
  // => die Dachflächen zeigen nach Norden und SÜDEN (nicht Ost/West!)
  const laenge = 6;      // Firstlänge (m)
  const breite = 4;      // Grundfläche quer zum First (m)
  const halbeBreite = breite / 2; // horizontale Tiefe je Dachfläche

  // typische Dachneigungen für Satteldach
  const neigungen = [30, 35, 40, 45];
  const results = neigungen.map(n => {
    const rad = n * Math.PI / 180;
    const tietheEbene = halbeBreite / Math.cos(rad); // tatsächliche Flächentiefe
    return { neigung: n, flaecheProSeite: +(laenge * tietheEbene).toFixed(1), tiefe: +tietheEbene.toFixed(2) };
  });

  // Modul: ca. 1.10 x 1.75 m (portrait), ~460 Wp modernes Modul
  // mit Randabstand ~ je 0,2-0,3 m und 2 Reihen hochkant
  const modulH = 1.75, modulB = 1.10, wp = 0.460;
  for (const r of results) {
    const nutztiefe = r.tiefe - 0.4;      // Randabstände oben/unten ~20cm
    const nutzlaenge = laenge - 0.6;      // Randabstände links/rechts ~30cm
    const reihen = Math.floor(nutztiefe / modulH);
    const proReihe = Math.floor(nutzlaenge / modulB);
    r.reihen = reihen; r.moduleProReihe = proReihe;
    r.moduleSued = reihen * proReihe;
    r.kwpSued = +(r.moduleSued * wp).toFixed(2);
    // Ertrag Süd-Ausrichtung, Mitteleuropa: ~950-1050 kWh/kWp je nach Ort
    r.ertragSued = [Math.round(r.kwpSued * 950), Math.round(r.kwpSued * 1050)];
  }

  // Miner-Beispiel: aktueller ASIC ~3.5 kW Leistungsaufnahme
  // Volllaststunden PV in D ~1000 h/kWp => wie lange läuft ein Miner damit?
  const kwp = 3;
  const ertrag = kwp * 1000; // kWh/Jahr
  const minerLeistung = 3.5; // kW
  const stunden = Math.round(ertrag / minerLeistung);
  const vollauslastungProzent = +(100 * stunden / 8760).toFixed(1);

  return { results, beispiel: { kwp, ertrag, stunden, vollauslastungProzent } };
}

async function main() {
  // Variante Querformat (landscape): Modul 1,75 m breit x 1,10 m hoch, ~460 Wp
  const laenge = 6, breite = 4;
  const modulB = 1.75, modulH = 1.10, wp = 0.460;
  const neigungen = [30, 35, 40, 45];
  const out = neigungen.map(n => {
    const rad = n * Math.PI / 180;
    const tiefe = (breite / 2) / Math.cos(rad);
    const nutztiefe = tiefe - 0.4;   // ~20 cm Rand oben+unten
    const nutzlaenge = laenge - 0.6; // ~30 cm Rand je Seite
    const reihen = Math.floor(nutztiefe / modulH);
    const proReihe = Math.floor(nutzlaenge / modulB);
    const module = reihen * proReihe;
    const kwp = +(module * wp).toFixed(2);
    return {
      neigung: n,
      tiefe: +tiefe.toFixed(2),
      reihen,
      moduleProReihe: proReihe,
      module,
      kwp,
      ertrag_kWh: Math.round(kwp * 950) + '–' + Math.round(kwp * 1050)
    };
  });
  return out;
}

