  const kwp1 = 2.76; // eigenes Dach
  const kwp2 = 2.76; // Nachbargebäude 3x6 m: ~6 Module quer bei Suedausrichtung
  const kwp = kwp1 + kwp2;
  const jahreskWh = Math.round(kwp * 1000);

  // Antminer S21 XP: 270 TH/s, 13,5 J/TH -> 3,645 kW; Hashprice ~35 €/PH/Tag
  const leistung = 3.645, hash = 0.27; // PH/s
  const hashprice = 35; // €/PH/Tag
  const volllaststunden = Math.round(jahreskWh / leistung);
  const revProTag = +(hash * hashprice).toFixed(2);        // €/Tag bei voller Sonne
  const revProKWh = +(revProTag / (leistung * 24) * 100).toFixed(1); // ct/kWh
  const evJahr = Math.round(volllaststunden / 24 * revProTag);

  // Solo-/Lottowahrscheinlichkeit: Netz ~960 EH/s, 144 Bloecke/Tag
  const netzwerkEH = 960000; // PH/s
  const share = hash / netzwerkEH;
  const bloeckeProJahrVolllast = 144 * share * (volllaststunden / 24);
  const pTreffer = +(bloeckeProJahrVolllast * 100).toFixed(2); // % pro Jahr
  const btcPreis = 73000;
  const jackpot = Math.round(3.2 * btcPreis); // 3,125 BTC Blockreward + Gebuehren

  // Vergleich: Einspeisung derselben Flaechen (falls moeglich) 12,22 ct
  const einspeisung = Math.round(jahreskWh * 0.1222);

  // Monatsprofil Volllaststunden
  const monate = ["Jan","Feb","Mär","Apr","Mai","Jun","Jul","Aug","Sep","Okt","Nov","Dez"];
  const kwh = [170, 250, 440, 590, 680, 700, 690, 620, 490, 320, 190, 140];
  const stunden = kwh.map(k => +(k / leistung).toFixed(0));

  return { kwp, jahreskWh, volllaststunden, revProTag, revProKWh, evJahr, pTreffer, jackpot, einspeisung, monate, stunden };
}

async function main() {
  // Annahmen Landkreis Barnim (Brandenburg), ~2,76 kWp Süd, ~40-45°
  const kwp = 2.76;
  const ertrag = Math.round(kwp * 1000); // ~1.000 kWh/kWp in Barnim (sonnenreiche Region Ost-D)

  // EEG-Vergütung ab Inbetriebnahme Aug 2026 - Jan 2027
  const voll = 12.22, teil = 7.70; // ct/kWh
  const eVoll = +(ertrag * voll / 100).toFixed(0);   // Volleinspeisung €/Jahr
  const eTeil = +(ertrag * teil / 100).toFixed(0);   // Teileinspeisung €/Jahr

  // Mining: Antminer S21 (200 TH/s, 3,5 kW, 17,5 J/TH), Hashprice ~$41/PH/Tag
  const hashratePH = 0.2, hashpriceUSD = 41, leistung = 3.5;
  const eurUsd = 0.86; // ca.
  const revenueProTagEUR = +(hashratePH * hashpriceUSD * eurUsd).toFixed(2); // €/Tag brutto
  const kwhProTag = leistung * 24;
  const revenueProKWh = +(revenueProTagEUR / kwhProTag * 100).toFixed(1);     // ct/kWh brutto

  // Szenario A: Miner läuft NUR mit Solarstrom (Inselbetrieb)
  const solarTage = ertrag / kwhProTag; // äquivalente Volllast-Tage/Jahr
  const miningSolarBrutto = +(solarTage * revenueProTagEUR).toFixed(0);       // €/Jahr
  // ASIC-Abschreibung über 3 Jahre: ~2.400 € / 3 = 800 €/Jahr
  const miningSolarNetto = +(miningSolarBrutto - 800).toFixed(0);

  // Szenario B: Miner 24/7 am Netzstrom (Haushaltspreis ~35 ct/kWh)
  const netzPreis = 0.35;
  const jahreskWh = Math.round(leistung * 8760);
  const kostenNetz = +(jahreskWh * netzPreis).toFixed(0);
  const revenueJahr = +(365 * revenueProTagEUR).toFixed(0);
  const miningNetzNetto = +(revenueJahr - kostenNetz).toFixed(0);

  return { ertrag, eVoll, eTeil, revenueProTagEUR, revenueProKWh, miningSolarBrutto, miningSolarNetto, jahreskWh, kostenNetz, revenueJahr, miningNetzNetto };
}

async function main() {
  // Eckdaten: PV 2,76 kWp -> 2.760 kWh/Jahr; Netzstrom 24 ct/kWh; Hashprice ~35,3 €/PH/Tag
  const ertrag = 2760;

  // Szenario 1: Volleinspeisung (12,22 ct)
  const s1 = Math.round(ertrag * 0.1222);

  // Szenario 2: Teileinspeisung mit 2.000 kWh Eigenverbrauch im Gebäude (spart 24 ct statt 7,70 ct Vergütung)
  const eigen = 2000;
  const s2 = Math.round(eigen * 0.24 + (ertrag - eigen) * 0.077);

  // Szenario 3: S21 (200 TH/s, 3,5 kW) 24/7 am 16A-Netzanschluss, 24 ct/kWh
  const jahreskWh = Math.round(3.5 * 8760);           // 30.660 kWh
  const revS21 = Math.round(0.2 * 35.3 * 365);        // ~2.573 €
  const s3 = revS21 - Math.round(jahreskWh * 0.24);

  // Szenario 4: Hybrid – Miner 24/7, PV deckt 2.760 kWh, Rest aus Netz
  const netzKWh = jahreskWh - ertrag;
  const s4 = revS21 - Math.round(netzKWh * 0.24);

  // Szenario 5: effizientester Luft-ASIC S21 XP (270 TH/s, 13,5 J/TH, ~3,65 kW) am Netz
  const kwhXP = Math.round(3.645 * 8760);
  const revXP = Math.round(0.27 * 35.3 * 365);        // ~3.478 €
  const s5 = revXP - Math.round(kwhXP * 0.24);

  // Randbedingungen 16A-Anschluss
  const anschlussKW = +(230 * 16 / 1000).toFixed(2);  // 3,68 kW
  const dauerlastKW = +(anschlussKW * 0.8).toFixed(1);// 80%-Regel
  const s21Ampere = +(3500 / 230).toFixed(1);         // 15,2 A

  // Erlös pro kWh je ASIC-Generation (ct/kWh)
  const eloS21 = +(revS21 / jahreskWh * 100).toFixed(1);
  const eloXP = +(revXP / kwhXP * 100).toFixed(1);

  return { s1, s2, s3, s4, s5, anschlussKW, dauerlastKW, s21Ampere, eloS21, eloXP, revS21, revXP };
}

async function main() {
  // Flachdach 3x6 m, 2,5 m hoch, Landkreis Barnim (~52,8°N)
  // Option A: 2 Reihen quer (landscape), 12° Sued, 6 Module a 460 Wp
  const A = { name: "6 Module Süd 12° (quer)", kwp: 2.76, spezifisch: 950 };
  // Option B: 8 Module Ost-West 10° (dichtere Belegung, flacheres Profil)
  const B = { name: "8 Module Ost-West 10°", kwp: 3.68, spezifisch: 800 };
  // Option C: 1 Reihe hochkant (portrait) 30° Sued, 3 Module
  const C = { name: "3 Module Süd 30° (hochkant)", kwp: 1.38, spezifisch: 1000 };
  const erg = [A, B, C].map(o => ({ ...o, kwh: Math.round(o.kwp * o.spezifisch) }));

  // Winterverschattung durch das 5-m-Gebaeude: Sonnenstand Wintersonnenwende
  const lat = 52.8;
  const elev = 90 - lat - 23.44;                 // ~13,8°
  const schatten5m = +(5 / Math.tan(elev * Math.PI / 180)).toFixed(0);
  const schattenRel = +((5 - 2.5) / Math.tan(elev * Math.PI / 180)).toFixed(0); // relativ zur Modulhoehe
  // Tagundnachtgleiche
  const elevEq = 90 - lat;
  const schattenEq = +((5 - 2.5) / Math.tan(elevEq * Math.PI / 180)).toFixed(1);

  return { erg, schatten5m, schattenRel, schattenEq };
}
